const input = $input.first().json;
const body = input.body ?? input;

const required = ['studentName', 'studentId', 'studentEmail', 'route', 'date', 'price', 'bookingRef', 'paymentRef', 'legs'];
const missing = required.filter((key) => body[key] === undefined || body[key] === null || body[key] === '');
if (missing.length) {
  throw new Error('Missing booking fields: ' + missing.join(', '));
}

const legs = Array.isArray(body.legs) ? body.legs : [];
if (!legs.length) {
  throw new Error('Booking must include at least one trip leg');
}

const bookingTypeLabel = legs.length > 1 ? 'Go and return' : (legs[0].kind === 'return' ? 'Return only' : 'Go only');

const legHtml = legs.map((leg) => {
  const color = leg.kind === 'return' ? '#a78bfa' : '#38bdf8';
  const qrUrl = leg.qrImageUrl || ('https://api.qrserver.com/v1/create-qr-code/?size=280x280&data=' + encodeURIComponent(leg.qrToken));
  return `<div style="margin-top:16px;padding:20px;background:#182231;border-left:4px solid ${color};border-radius:10px;text-align:center;">
    <h2 style="margin:0 0 8px;color:${color};font-size:18px;">${leg.label} — ${leg.labelAr || ''}</h2>
    <div style="color:#cbd5e1;font-size:13px;margin-bottom:12px;">${leg.date} · ${leg.time} · Seat ${leg.seatNumber}</div>
    <div style="color:#94a3b8;font-size:13px;margin-bottom:14px;">${leg.pickup} → ${leg.dropoff}</div>
    <img src="${qrUrl}" width="220" height="220" alt="${leg.label} QR code" style="display:block;margin:0 auto;background:#ffffff;border-radius:10px;padding:8px;" />
    <div style="margin-top:14px;color:#94a3b8;font-size:12px;">Manual boarding code</div>
    <div style="font-family:monospace;font-size:22px;font-weight:700;letter-spacing:3px;color:#ffffff;margin-top:4px;">${leg.boardingCode}</div>
  </div>`;
}).join('');

const html = `<div style="font-family:Segoe UI,Arial,sans-serif;max-width:620px;margin:0 auto;background:#10141d;color:#f8fafc;border-radius:18px;overflow:hidden;">
  <div style="padding:28px 30px;background:linear-gradient(135deg,#111827,#26354a);">
    <div style="color:#60a5fa;font-size:13px;letter-spacing:1px;text-transform:uppercase;">Galala University Transport</div>
    <h1 style="margin:8px 0 0;font-size:24px;color:#ffffff;">Your bus ticket is confirmed</h1>
  </div>
  <div style="padding:28px 30px;">
    <div style="display:inline-block;padding:7px 11px;border:1px solid #475569;border-radius:999px;color:#cbd5e1;font-family:monospace;font-size:13px;">REF ${body.bookingRef}</div>
    <table style="width:100%;border-collapse:collapse;margin:22px 0 8px;font-size:14px;">
      <tr><td style="padding:8px 0;color:#94a3b8;width:38%;">Student</td><td style="padding:8px 0;color:#ffffff;font-weight:700;">${body.studentName}</td></tr>
      <tr><td style="padding:8px 0;color:#94a3b8;">Student ID</td><td style="padding:8px 0;color:#ffffff;">${body.studentId}</td></tr>
      <tr><td style="padding:8px 0;color:#94a3b8;">Email</td><td style="padding:8px 0;color:#ffffff;">${body.studentEmail}</td></tr>
      <tr><td style="padding:8px 0;color:#94a3b8;">Trip</td><td style="padding:8px 0;color:#ffffff;">${body.route} · ${body.date}</td></tr>
      <tr><td style="padding:8px 0;color:#94a3b8;">Type</td><td style="padding:8px 0;color:#ffffff;">${bookingTypeLabel}</td></tr>
      <tr><td style="padding:8px 0;color:#94a3b8;">Price</td><td style="padding:8px 0;color:#ffffff;font-weight:700;">${body.price}</td></tr>
      <tr><td style="padding:8px 0;color:#94a3b8;">Payment</td><td style="padding:8px 0;color:#ffffff;font-family:monospace;">${body.paymentRef}</td></tr>
    </table>
    ${legHtml}
    <p style="margin:20px 0 0;color:#94a3b8;font-size:12px;">Show the matching QR or manual code when you board: one for going, and one for returning if you booked both.</p>
  </div>
</div>`;

return [{
  json: {
    studentEmail: body.studentEmail,
    bookingRef: body.bookingRef,
    subject: `Bus ticket confirmed — ${body.bookingRef}`,
    html,
  },
}];
